package vn.edu.eaut.lab6.filter; import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;@WebFilter(urlPatterns={"/student-form.jsp","/student-edit","/student-delete"}) public class AdminFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)a;HttpServletResponse p=(HttpServletResponse)b;HttpSession s=q.getSession(false);if(s!=null&&"ADMIN".equals(s.getAttribute("role")))c.doFilter(a,b);else p.sendRedirect(q.getContextPath()+"/403.jsp");}}
